class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        return build(preorder, 0, 0, inorder.length, inorder);
    }

    private TreeNode build(int[] preorder, int preStart, int inStart, int inEnd, int[] inorder) {
        if (inStart >= inEnd) {
            return null;
        }
        int rootValue = preorder[preStart];
        int split = inStart;
        while (inorder[split] != rootValue) {
            split++;
        }
        int leftSize = split - inStart;
        TreeNode root = new TreeNode(rootValue);
        root.left = build(preorder, preStart + 1, inStart, split, inorder);
        root.right = build(preorder, preStart + leftSize + 1, split + 1, inEnd, inorder);
        return root;
    }
}

