import java.util.HashMap;
import java.util.Map;

class Solution {
    private Map<Integer, Integer> inorderIndex;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        inorderIndex = new HashMap<>();
        for (int index = 0; index < inorder.length; index++) {
            inorderIndex.put(inorder[index], index);
        }
        return build(preorder, 0, 0, inorder.length);
    }

    private TreeNode build(int[] preorder, int preStart, int inStart, int inEnd) {
        if (inStart >= inEnd) {
            return null;
        }
        int rootValue = preorder[preStart];
        int split = inorderIndex.get(rootValue);
        int leftSize = split - inStart;
        TreeNode root = new TreeNode(rootValue);
        root.left = build(preorder, preStart + 1, inStart, split);
        root.right = build(preorder, preStart + leftSize + 1, split + 1, inEnd);
        return root;
    }
}
